"""Fixture-independent Geometry Nodes fields over analytic input records."""
from .common import V

MAX_PIECES = 3


def choose(g, condition, yes, no, kind='FLOAT'):
    node = g.node('GeometryNodeSwitch')
    node.input_type = kind
    g.bind(condition, node.inputs['Switch'])
    g.bind(yes, node.inputs['True']); g.bind(no, node.inputs['False'])
    return V(g, node.outputs['Output'])


def bounded(g, value, low=0., high=1.):
    return g.math('MINIMUM', g.math('MAXIMUM', value, low), high)


def smooth(t):
    return t*t*t*(10.+t*(-15.+6.*t))


def equal(g, first, second):
    node = g.node('ShaderNodeMath', 'Exact record comparison')
    node.operation = 'COMPARE'
    g.bind(first, node.inputs[0]); g.bind(second, node.inputs[1])
    node.inputs[2].default_value = 0.
    return V(g, node.outputs[0])


def named(g, name, kind='FLOAT'):
    node = g.node('GeometryNodeInputNamedAttribute', name)
    node.data_type = kind
    node.inputs['Name'].default_value = name
    return V(g, node.outputs['Attribute'])


def read(g, geo, name, index, kind='FLOAT'):
    """An explicit Sample Index makes record values single for single indices.

    This is essential when a Repeat iteration chooses a record whose sampled
    integer then controls Grid vertex counts. Named Attribute alone is a field.
    """
    node = g.node('GeometryNodeSampleIndex', 'Read record / '+name)
    node.data_type = kind; node.domain = 'POINT'; node.clamp = False
    g.bind(geo, node.inputs['Geometry'])
    g.bind(named(g, name, kind), node.inputs['Value'])
    g.bind(index, node.inputs['Index'])
    return V(g, node.outputs['Value'])


def count(g, geo):
    node = g.node('GeometryNodeAttributeDomainSize', 'Record count')
    node.component = 'MESH'
    g.bind(geo, node.inputs['Geometry'])
    return V(g, node.outputs['Point Count'])


def split(g, geo, record_type):
    node = g.node('GeometryNodeSeparateGeometry', 'Record view / '+str(record_type))
    node.domain = 'POINT'
    g.bind(geo, node.inputs['Geometry'])
    g.bind(equal(g, named(g, 'record_type', 'INT'), record_type), node.inputs['Selection'])
    return V(g, node.outputs['Selection'])


def profile(g, plateau, s, denominator=None):
    denominator = (1.-plateau) if denominator is None else denominator
    r = g.math('MAXIMUM', (s-plateau)/denominator, 0.)
    return 1.-r*r


def bezier(g, patches, index, t):
    K = [g.separate(read(g, patches, name, index, 'FLOAT_VECTOR'))
         for name in ('K0', 'K1_3', 'K2_3', 'K3')]
    return [K[0][j]*(1.-t)**3 + K[1][j]*t*(1.-t)**2
            + K[2][j]*t*t*(1.-t) + K[3][j]*t**3 for j in (0, 1)]


def angular(g, patches, pieces, index, raw, *, max_pieces=MAX_PIECES):
    """Uniform baseline mapping with all mandatory fillet tangent knots."""
    start = read(g, patches, 'piece_start', index, 'INT')
    number = read(g, patches, 'piece_count', index, 'INT')
    mode = read(g, patches, 'angular_mode', index, 'INT')
    result = raw
    intervals = []
    for i in range(max_pieces):
        at = start+i
        lo, t0, du, dt = [read(g, pieces, name, at) for name in ('u0', 't0', 'u_span', 't_span')]
        candidate = t0 + bounded(g, (raw-lo)/du)*dt
        active = g.math('GREATER_THAN', number, i)
        if i:
            active = active*g.math('GREATER_THAN', raw, lo)
        result = choose(g, active, candidate, result)
        intervals.append((lo, t0))
    for i in range(1, max_pieces):
        lo, t0 = intervals[i]
        active = g.math('GREATER_THAN', number, i)*equal(g, raw, lo)
        result = choose(g, active, t0, result)
    fraction = read(g, patches, 'split_fraction', index)
    split_value = choose(g, g.math('GREATER_THAN', raw, .5),
                         fraction+(2.*raw-1.)*(1.-fraction), 2.*raw*fraction)
    return choose(g, equal(g, mode, 2), split_value,
                  choose(g, equal(g, mode, 1), result, raw))


def outer(g, patches, pieces, index, t, *, max_pieces=MAX_PIECES):
    """Bounded analytic boundary evaluator; ordinary corners retain three pieces."""
    start = read(g, patches, 'piece_start', index, 'INT')
    number = read(g, patches, 'piece_count', index, 'INT')
    distance = t*read(g, patches, 'outer_length', index)
    result = [0., 0.]
    for i in range(max_pieces):
        at = start+i
        kind = read(g, pieces, 'kind', at, 'INT')
        offset = read(g, pieces, 'offset', at)
        f = bounded(g, (distance-offset)/read(g, pieces, 'length', at))
        p, delta, center, tangent, right = [g.separate(read(g, pieces, name, at, 'FLOAT_VECTOR'))
            for name in ('start', 'delta', 'center', 'tangent', 'right')]
        angle = read(g, pieces, 'start_angle', at)+read(g, pieces, 'sweep', at)*f
        radius = read(g, pieces, 'radius', at)
        arc = [center[0]+radius*g.math('COSINE', angle), center[1]+radius*g.math('SINE', angle)]
        ds, dq = read(g, pieces, 'ds', at), read(g, pieces, 'dq', at)
        taper = [p[j]+ds*f*tangent[j]+dq*smooth(f)*right[j] for j in (0, 1)]
        line = [p[j]+f*delta[j] for j in (0, 1)]
        point = [choose(g, equal(g, kind, 1), arc[j], choose(g, equal(g, kind, 2), taper[j], line[j]))
                 for j in (0, 1)]
        active = g.math('GREATER_THAN', number, i)
        if i:
            active = active*g.math('GREATER_THAN', distance, offset)
        result = [choose(g, active, point[j], result[j]) for j in (0, 1)]
    return result
